"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["81222"],{96177(t){t.exports=JSON.parse('{"id":"FIN-033","slug":"opportunity-cost","term":"Opportunity Cost","also_known_as":[],"difficulty":"Beginner","definition":"Opportunity cost is the value of the best alternative you give up when you make a choice. Every decision to use time or money one way means not using it another way.","explanation":["Resources such as money, time and effort are limited, so choosing one option always means giving something up. The opportunity cost is the benefit of the best option you did not choose, not the sum of every alternative.","Suppose you have 5,000. You could spend it on a holiday, or invest it and expect it to earn about 6% a year. If you take the holiday, the opportunity cost is not only the 5,000 itself but also the roughly 300 a year it might have earned, and the growth that would have built on top of that over time.","Opportunity cost applies to time too. If you spend a Saturday doing your own home repairs instead of working an extra shift that pays 150, the opportunity cost of doing it yourself is the 150 you could have earned.","Businesses use the same idea. Money tied up in unsold inventory could have been used for marketing or to pay down debt. Thinking in terms of opportunity cost helps people and companies compare options fairly instead of looking only at the price tag."],"note":"","total":1725,"prev":{"slug":"operational-risk","term":"Operational Risk"},"next":{"slug":"optimal-capital-structure","term":"Optimal Capital Structure"}}')}}]);